export const stamp = (at: number) => new Date(at).toLocaleString()
export const day = (at: Date) => at.toLocaleDateString("ja")
export const clock = (at?: Date) => at?.toLocaleTimeString()
export const amount = (n: number) => n.toLocaleString()
export const dates = new Intl.DateTimeFormat(undefined, { dateStyle: "short" })
export const relative = new Intl.RelativeTimeFormat("en")
export const plural = new Intl.PluralRules("en")
export const numbers = new Intl.NumberFormat("en")
export const zone = Intl.DateTimeFormat().resolvedOptions().timeZone
export const initial = (name: string) => name.toLocaleUpperCase()
export const graphemes = new Intl.Segmenter(undefined, { granularity: "grapheme" })
